import{_ as o,o as n,c as t,ag as i}from"./chunks/framework.B_zcDAFh.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),a={name:"guide/index.md"};function r(s,e,d,c,u,l){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Boing Kit is a Unity asset for spring-based procedural animation, published by Long Bunny Labs and authored by Ming-Lun &quot;Allen&quot; Chou. Everything lives under the <code>BoingKit</code> namespace and is centered on a single static manager (<code>BoingManager</code>) that owns all per-frame execution.</p><p>The kit covers four interlocking systems: single-point spring behaviors, bone-chain spring solvers, point effectors that push reactors, and volumetric reactor fields that can be sampled on either CPU or GPU. Work is dispatched through <code>BoingWorkSynchronous</code> or — on Unity 2018.1+ — <code>BoingWorkAsynchronous</code> (Unity Jobs / Burst), selectable via <code>BoingManager.UseAsynchronousJobs</code>.</p>',3)])])}const g=o(a,[["render",r]]);export{h as __pageData,g as default};
